#[test]
    fn test_qalloc_qfree_reset_circuit() {
        use hugr::builder::{DFGBuilder, Dataflow, DataflowHugr};
        use hugr::extension::prelude::QB_T;
        use hugr::types::FunctionType;

        let qb_row = vec![QB_T];
        let mut h = DFGBuilder::new(FunctionType::new(qb_row.clone(), qb_row.clone())).unwrap();
        let [q_in] = h.input_wires_arr();

        // Allocate a fresh qubit, reset it, and pass it on as the circuit output.
        let q_alloc = h.add_dataflow_op(Tk2Op::QAlloc, []).unwrap().out_wire(0);
        let q_out = h
            .add_dataflow_op(Tk2Op::Reset, [q_alloc])
            .unwrap()
            .out_wire(0);

        // Free the input qubit.
        h.add_dataflow_op(Tk2Op::QFree, [q_in]).unwrap();

        let circ = h.finish_hugr_with_outputs([q_out], &crate::extension::REGISTRY).unwrap();

        // The commands are QAlloc, Reset, and QFree.
        assert_eq!(circ.commands().count(), 3);

        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::QAlloc))
                .count(),
            1
        );
        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::Reset))
                .count(),
            1
        );
        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::QFree))
                .count(),
            1
        );

        // The new ops are not quantum operations.
        assert!(!Tk2Op::is_quantum(&Tk2Op::QAlloc));
        assert!(!Tk2Op::is_quantum(&Tk2Op::QFree));
        assert!(!Tk2Op::is_quantum(&Tk2Op::Reset));
        assert!(Tk2Op::is_quantum(&Tk2Op::H));
    }

