#[test]
    fn test_qalloc_qfree_reset_circuit() {
        use hugr::builder::{DFGBuilder, Dataflow, DataflowHugr};
        use hugr::extension::prelude::QB_T;
        use hugr::types::FunctionType;

        let qb_row = vec![QB_T];
        let mut h = DFGBuilder::new(FunctionType::new(qb_row.clone(), qb_row)).unwrap();
        let [q_in] = h.input_wires_arr();

        // Allocate a fresh qubit.
        let q_alloc = h.add_dataflow_op(Tk2Op::QAlloc, []).unwrap().out_wire(0);

        // Reset both the input and the newly allocated qubits.
        let q_in = h.add_dataflow_op(Tk2Op::Reset, [q_in]).unwrap().out_wire(0);
        let q_alloc = h.add_dataflow_op(Tk2Op::Reset, [q_alloc]).unwrap().out_wire(0);

        // Free both qubits.
        h.add_dataflow_op(Tk2Op::QFree, [q_in]).unwrap();
        h.add_dataflow_op(Tk2Op::QFree, [q_alloc]).unwrap();

        let circ = h.finish_hugr_with_outputs([], &crate::extension::REGISTRY).unwrap();

        // The commands are QAlloc, Reset, Reset, QFree, QFree.
        assert_eq!(circ.commands().count(), 5);
        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::QAlloc))
                .count(),
            1
        );
        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::Reset))
                .count(),
            2
        );
        assert_eq!(
            circ.commands()
                .filter(|command| op_matches(command.optype(), Tk2Op::QFree))
                .count(),
            2
        );
    }

