/// Calculate depth by placing commands in slices.
    fn depth(h: &Hugr) -> usize {
        load_slices(h).len()
    }

    /// Apply the greedy depth reduction pass and check the expected outcome.
    ///
    /// Asserts that the pass returns the expected number of commutations,
    /// decreases (or preserves) the circuit depth as expected, leaves the
    /// circuit valid, and does not change the number of nodes.
    fn check_min_count_and_depth(mut case: Hugr, should_reduce: bool, expected_moves: u32) {
        let node_count = case.node_count();
        let depth_before = depth(&case);
        let move_count = apply_greedy_commutation(&mut case).unwrap();
        case.update_validate(&REGISTRY).unwrap();

        assert_eq!(
            move_count, expected_moves,
            "Number of commutations did not match expected."
        );
        let depth_after = depth(&case);

        if should_reduce {
            assert!(depth_after < depth_before, "Depth should have decreased..");
        } else {
            assert_eq!(
                depth_before, depth_after,
                "Depth should not have changed for this case."
            );
        }

        assert_eq!(
            case.node_count(),
            node_count,
            "depth optimisation should not change the number of nodes."
        )
    }

    #[rstest]
    #[case(example_cx(), true, 1)]
    #[case(example_cx_better(), false, 0)]
    #[case(big_example(), true, 1)]
    #[case(cant_commute(), false, 0)]
    #[case(t2_bell_circuit(), false, 0)]
    #[case(single_qb_commute(), true, 1)]
    #[case(single_qb_commute_2(), true, 2)]
    #[case(commutes_but_same_depth(), false, 1)]
    #[case(non_linear_inputs(), true, 1)]
    #[case(non_linear_outputs(), true, 1)]
    fn commutation_example(
        #[case] case: Hugr,
        #[case] should_reduce: bool,
        #[case] expected_moves: u32,
    ) {
        check_min_count_and_depth(case, should_reduce, expected_moves)
    }

    // Regression test for bug
    // https://github.com/CQCL/tket2/issues/253.
    //
    // This 3-qubit circuit previously triggered a conversion bug in the greedy
    // depth reduction pass, which produced an invalid circuit when pulling the
    // last CX commutation forwards.
    #[test]
    fn test_cx_commute_bug() {
        check_min_count_and_depth(cx_commute_bug(), true, 1)
    }
}

